-- Generated by scripts/sync-catalog.ts from content/lessons/*.json (requirement 1.4).
-- DO NOT EDIT BY HAND. Re-run `npm run sync:catalog` after changing lesson content.
-- Seeds lessons_catalog and feature_unlock_rules
-- (supabase/migrations/20250104000001_learning_tables.sql).

on conflict (lesson_id) do update set
  unit = excluded.unit,
  sort_order = excluded.sort_order,
  kind = excluded.kind,
  xp_base = excluded.xp_base,
  pass_score = excluded.pass_score,
  prerequisite_lesson_id = excluded.prerequisite_lesson_id;

on conflict (feature_key) do update set
  lesson_id = excluded.lesson_id,
  description = excluded.description;
